// Original coarse outlines, generalized from the references listed below.
// [longitude, latitude]; not GIS boundaries, not suitable for area measurement.
window.TERRITORIES = {
 qin: {name:'秦',period:'約前220年（參考圖標年）',color:'#c17438',center:[32,111],source:'loc',note:'以秦統一初期的參考概覽圖為線索；邊緣與南方擴張經過高度簡化，不能視為該年各地行政控制的精確紀錄。',rings:[[[103,38],[108,40],[113,40],[118,41],[121,42],[122,41],[120,39],[118,38],[119,36],[121,35],[120,32],[121,30],[120,28],[117,29],[113,29],[113,26],[111,24],[108,22],[106,22],[108,25],[108,28],[105,29],[102,29],[101,31],[102,34],[103,38]]]},
 tang: {name:'唐／武周',period:'700年 · 主體統治區示意',color:'#ac5277',center:[33,108],source:'loc',note:'700年位於武周時期（690–705）。沿用參考圖的唐代分組，只概括圖示主體統治區；西域都護府、羈縻與勢力範圍未完整呈現，不能當作唐代最大版圖。',rings:[[[94,40],[98,40],[101,38],[105,38],[108,39],[113,40],[118,42],[122,42],[123,41],[121,39],[119,39],[118,37],[120,37],[122,35],[120,33],[121,30],[121,28],[119,25],[116,23],[112,21],[109,21],[107,20],[106,22],[108,24],[106,26],[104,26],[103,28],[101,26],[100,28],[101,31],[103,34],[101,36],[98,38],[94,39],[94,40]]]},
 song: {name:'北宋',period:'北宋時期（960–1127）概覽',color:'#477ba0',center:[32,112],source:'song',note:'以北宋時期概覽圖重繪，不代表960–1127年間疆域不變。北方與遼、西夏並立，西南有大理；這些並存政權未完整呈現。北京不在本圖的宋境內。',rings:[[[103,35],[106,34],[109,35],[111,37],[112,39],[115,39],[117,38],[118,38],[119,37],[122,37],[121,35],[120,33],[121,31],[122,29],[121,27],[119,25],[117,23],[113,22],[110,21],[108,21],[107,23],[105,24],[105,26],[103,27],[104,29],[102,30],[102,33],[103,35]]]},
 southernSong: {name:'南宋',period:'南宋時期（1127–1279）概覽',color:'#41846c',center:[29,112],source:'song',note:'以南宋時期概覽圖重繪，淮河一帶邊界為概括示意。開封已不在宋境內，臨安（今杭州）成為都城；金、西夏、大理等並存政權未完整呈現。',rings:[[[103,33],[107,33],[110,32.8],[113,32.5],[115,31.8],[117,32.5],[119,33],[120,33],[121,31],[122,29],[121,27],[119,25],[117,23],[113,22],[110,21],[108,21],[107,23],[105,24],[105,26],[103,27],[104,29],[102,30],[102,32],[103,33]]]},
 ming: {name:'明',period:'約1580年',color:'#7970ac',center:[33,109],source:'loc',note:'參照約1580年主體統治區概覽；邊地控制有不同形式，海上活動也不等於領土。未呈現全部並存政權，不能當作明代各時期疆域的總和。',rings:[[[96,40],[99,40],[100,38],[103,37],[106,37],[109,38],[112,40],[116,41],[120,43],[124,43],[124,41],[122,40],[120,39],[118,39],[118,37],[121,37],[122,36],[120,34],[121,31],[122,29],[120,26],[118,24],[114,22],[110,21],[108,21],[106,22],[104,22],[102,23],[99,23],[98,25],[100,27],[102,28],[102,31],[104,33],[104,35],[101,36],[99,38],[96,39],[96,40]],[[108.6,20],[111,20],[110.5,18.2],[109,18],[108.6,20]]]}
};
(()=>{'use strict';const $=s=>document.querySelector(s);let selected='song',land=null;
const project=([lon,lat])=>[(lon-85)/50*640,(48-lat)/34*420];
const path=ring=>ring.map((p,i)=>`${i?'L':'M'}${project(p).map(v=>v.toFixed(1)).join(' ')}`).join(' ')+'Z';
const sources={loc:['美國國會圖書館｜China: A Country Study，圖2，印刷頁12','https://tile.loc.gov/storage-services/master/frd/frdcstdy/ch/chinacountrystud00word/chinacountrystud00word.pdf#page=60','參考圖標示約前220年、700年、約1580年；本圖重新概括繪製，不是數位化測繪疆界。'],song:['哥倫比亞大學｜The Song Dynasty and Its Rivals','https://afe.easia.columbia.edu/songdynasty-module/outside-rivals.html','依北宋與南宋概覽的地理關係原創重繪，未重製來源圖片；來源沒有給出單一年份，因此使用時期標示。']};
function render(){const t=TERRITORIES[selected],visible=$('#territoryVisible').checked;$('#territorySelect').value=selected;$('#territoryCaption').innerHTML=`<span class="territory-swatch" style="background:${t.color};color:${t.color}"></span><strong>${t.name} · ${t.period}</strong><br>${t.note}`;const s=sources[t.source];$('#territorySource').innerHTML=`<p><a href="${s[1]}" target="_blank" rel="noopener noreferrer">${s[0]} ↗</a><br>${s[2]}</p>`;
const coast=land?land.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates).map(poly=>`<path d="${poly.map(path).join(' ')}"/>`).join(''):'';
$('#territoryMap').innerHTML=`<svg viewBox="0 0 640 420" role="img" aria-labelledby="territorySvgTitle territorySvgDesc"><title id="territorySvgTitle">${t.name}疆域概略示意</title><desc id="territorySvgDesc">${t.period}。${t.note} ${visible?'色塊顯示中':'疆域色塊已隱藏'}。同一經緯度範圍，不是等積投影。</desc><defs><clipPath id="territoryLandClip">${coast}</clipPath><clipPath id="territoryClip"><rect width="640" height="420"/></clipPath></defs><g clip-path="url(#territoryClip)"><rect width="640" height="420" fill="#d2e3de"/><g fill="#e9ede1" stroke="#a6bfb1" stroke-width="1" fill-rule="evenodd">${coast}</g><g fill="none" stroke="#91aaa0" opacity=".4" stroke-width=".6">${[90,100,110,120,130].map(l=>`<path d="M${project([l,48])[0]} 0 V420"/>`).join('')}${[20,30,40].map(l=>`<path d="M0 ${project([85,l])[1]} H640"/>`).join('')}</g><g ${land?'clip-path="url(#territoryLandClip)"':''} class="territory-fill" fill="${t.color}" fill-opacity=".38" stroke="${t.color}" stroke-width="2" stroke-dasharray="5 4" ${visible?'':'visibility="hidden"'}>${t.rings.map(r=>`<path d="${path(r)}"/>`).join('')}</g>${[[108.94,34.26,'長安',-7,-12],[114.31,34.8,'開封',8,-5],[120.16,30.25,'杭州',8,5],[116.4,39.9,'北京',8,-7]].map(([lon,lat,name,dx,dy])=>{const [x,y]=project([lon,lat]);return `<circle cx="${x}" cy="${y}" r="3" fill="#233d34"/><text x="${x+dx}" y="${y+dy}" font-size="12" fill="#233d34" stroke="#f7f5ed" stroke-width="3" paint-order="stroke">${name}</text>`}).join('')}</g><text x="16" y="25" font-size="12" fill="#233d34">${t.name} · ${t.period}</text><text x="602" y="25" font-size="12" fill="#233d34">北 ↑</text></svg><p class="territory-map-note">${land?'現代海岸線定位':'海岸底圖載入中；經緯網與疆域仍可比較'} · 虛線邊界為概括示意。試著比較：北宋變成南宋後，開封的位置有什麼改變？</p>`;
window.historyGlobe?.territory?.(t,visible);
}
window.historyTerritories={select(id){if(!TERRITORIES[id])return;selected=id;render()},current:()=>TERRITORIES[selected],visible:()=>$('#territoryVisible').checked,render};
$('#territorySelect').onchange=()=>{selected=$('#territorySelect').value;render()};$('#territoryVisible').onchange=render;render();
if(typeof fetch==='function')fetch('./land.geojson').then(r=>{if(!r.ok)throw Error('land');return r.json()}).then(data=>{land=data;render()}).catch(()=>{const el=$('#territoryMap .territory-map-note');if(el)el.textContent='海岸底圖未能載入；疆域與經緯網仍可顯示。請搭配文字與來源閱讀。'});
})();
